INSERT INTO fact (id,subject_id,text,provenance_class,trust_class,source_url,source_host,source_date,observed_at,composed_from,search_first_page,via_edge_type,via_person_id,run_id) VALUES

-- ── sarahtavel.com (Substack), her live blog. Self-published, subject-authored ──
('f_tavel_001','m_tavel','Stepped back from General Partner to VENTURE PARTNER at Benchmark on 2025-04-29, in her own announcement: "After eight years at Benchmark, I''m shifting to a Venture Partner role. In this new role, I''ll continue to make new investments on behalf of Benchmark, serve on my existing boards, and contribute to Benchmark and our portfolio. What''s changing is my focus and time allocation." Her reason: "for me to best support founders building in AI, I need more space. More space to go AI-native by fully immersing myself in AI tools at the edge, more space to reflect on the last ten years... and maybe even (don''t hold me to this!) more space to think through it all by writing."','self_published','subject_authored','https://www.sarahtavel.com/p/my-new-role-at-benchmark','sarahtavel.com','2025-04-29','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_002','m_tavel','On why Benchmark''s structure demands what it does: "a small equal partnership of no more than six general partners, all generalists, deeply committed to partnering with the most ambitious founders of our generation. With no junior people or platform team, the structure demands total dedication from each partner."','self_published','subject_authored','https://www.sarahtavel.com/p/my-new-role-at-benchmark','sarahtavel.com','2025-04-29','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_003','m_tavel','Co-signed Benchmark''s announcement of Victor Lazarte as General Partner — "Peter, Eric, Sarah, Chetan, and Miles" — and set out the firm''s own definition of itself: "the firm remains defined by the simple, clear model of six equal General Partners, each operating with the autonomy and ownership of a founder in the fullest sense — from compensation to decision making authority... At Benchmark, we strive to offer a radically different level of service and commitment to the founders we serve. Done this way, venture does not scale."','self_published','subject_authored','https://www.sarahtavel.com/p/benchmarks-new-general-partner-victor','sarahtavel.com','2023-07-24','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_004','m_tavel','On performance review design, drawing on both her former employers: "at Pinterest, we had a 2x2 where one axis was ''Impact'', and the other was ''Values''. According to my former Greylock partner John Lilly, at Mozilla they talked about impact across project and company."','self_published','subject_authored','https://www.sarahtavel.com/p/the-mitochondria-in-startups','sarahtavel.com','2023-07-25','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_005','m_tavel','A Pinterest failure told against herself: the growth team rebuilt the new-user experience by studying Instagram''s "like it was a map", shipped something "honestly, weak", and the metrics showed it immediately; the rebuild got deprioritised and "Pinterest went through a period of hyper growth with an underperforming NUX." Months later she signed out of Twitter to look at theirs — "They''d updated it… to something similar to Pinterest''s. The NUX that we knew was under performing."','self_published','subject_authored','https://www.sarahtavel.com/p/dont-fall-into-the-trap-of-taking','sarahtavel.com','2023-07-14','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_006','m_tavel','Her Substack, sarahtavel.com, holds exactly 23 posts across its whole life, 2023-02-22 to 2025-09-03 — about 0.74 posts a month, and bursty: eight of them fall between 2025-01-14 and 2025-09-03, and nothing has been published there in the twelve months since. The masthead changed under her: "Rougher Thoughts by Sarah Tavel" in 2023, "Sarah Tavel''s Newsletter" by 2025.','self_published','subject_authored','https://www.sarahtavel.com/api/v1/archive?sort=new&limit=50&offset=0','sarahtavel.com','2025-09-03','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_007','m_tavel','Substack profile bio, verbatim: "Blogging since 2006. Partner @benchmark. formerly: product @pinterest. vc @greylockvc, @bessemervp." Profile created 2023-01-04.','self_published','subject_authored','https://www.sarahtavel.com/api/v1/publication/users/ranked?public=true','sarahtavel.com','2023-01-04','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

-- ── medium.com/@sarahtavel — the HTML 403s, the feed does not ─────────────────
('f_tavel_008','m_tavel','Her Medium feed carries ten items, 2023-01-04 to 2024-04-02, opening with "Trying something new — Weekly Thoughts" and closing with "AI Startups: 100x and cheaper"; she cross-posted the same essays to Substack. Nothing has appeared there since 2024-04-02. (medium.com/@sarahtavel returns 403 to automated clients; the feed is the only readable surface, and it is a ten-item window, not a lifetime count.)','self_published','subject_authored','https://medium.com/feed/@sarahtavel','medium.com','2024-04-02','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

-- ── X, logged in. Bio/counts/post bodies only; personalization stripped ───────
('f_tavel_009','m_tavel','X bio, verbatim: "Partner at @Benchmark. Student of escaping competition. Formerly product @pinterest. Ball and chain for @cklemke and 🧒🏽👧🏻👶🏻." Location "san francisco", website sarahtavel.com, joined May 2008, 9,417 posts, 1,435 following, 52,899 followers.','self_published','subject_authored','https://x.com/sarahtavel','x.com','2026-09-03','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_010','m_tavel','On her mother, in her own words: "Happy Mother''s Day to all the moms out there, esp (for me!) @susavel. ❤️ Immigrated to the US from Argentina in 1973 with a suitcase, $200, and one share of IBM stock. Lived the American dream. Raised five kids. Grateful to her, and to this country for making it possible."','self_published','subject_authored','https://x.com/sarahtavel','x.com','2021-05-09','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_011','m_tavel','Argues for stablecoins from family experience: "Another way to look at crypto to get you out of US-centric thinking: We''re used to looking at crypto prices in USD. Imagine if you have a high-inflation local currency (like my family in Argentina). This is Bitcoin in Argentine Pesos." In the same thread: "To be clear, what people want in Argentina is a USD... it''s the king. But my point is more that looking at Bitcoin in terms of local currency also lends more credence to crypto. Helps people get more curious / comfortable with USD stablecoins."','self_published','subject_authored','https://x.com/sarahtavel','x.com','2024-01-24','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_012','m_tavel','Why the blog is quiet, from her own X account, quoting Farhan Thawar quoting Kevin Kelly ("The most common mistake we make is to do a great job on an unimportant task"): "The secret fear they keeps making my blog post draft list longer and longer. 🤣"','self_published','subject_authored','https://x.com/sarahtavel','x.com','2026-08-30','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_013','m_tavel','"I have no connection to @fortellresearch but having read about them, I gifted my mom their hearing aids and it''s been a game changer for her. Only problem is she''s more excited about being able to eavesdrop on people''s conversations in the gym than hear us when out to dinner. :)"','self_published','subject_authored','https://x.com/sarahtavel','x.com','2026-08-12','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_014','m_tavel','She is not dormant. Her own X timeline carries posts on 2026-08-31 ("Love the two week follow up question of what name people remembered"), 2026-08-30, 2026-08-20 ("So much wisdom here on references. Thank you @dittycheria for continuing to share yours!"), 2026-08-12 and 2026-07-18 — the newest three days before this run, while her blog had been silent for twelve months.','self_published','subject_authored','https://x.com/sarahtavel','x.com','2026-08-31','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_015','m_tavel','Replied to Fred Wilson, once, on X — to @danprimack and @fredwilson: "great interview". This is the only appearance of the handle @fredwilson anywhere in her own X output.','self_published','subject_authored','https://x.com/sarahtavel','x.com','2016-02-08','2026-09-03T23:55:00Z',NULL,1,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_016','m_tavel','Replied to Josh Kopelman (@joshk) twice on X: "wow that was pretty good" (2016-08-21) and "great way of putting it" (2019-01-11).','self_published','subject_authored','https://x.com/sarahtavel','x.com','2019-01-11','2026-09-03T23:55:00Z',NULL,1,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_017','m_tavel','Hunter Walk is the one member of the room she talks TO, repeatedly and casually, over seven years of X replies: "Not too much of a break please. I depend on his social validation of my tweets. Happy birthday Hunter!" (2020-09-18); "The three squares is my recipe for happiness too! So glad you are enjoying." (2020-10-11); "you are funny" (2020-10-05); "jelly" (2020-05-12); "spurts indeed! thanks for including it. :)" (2023-09-05). Earlier, in 2016, she quoted a Valleywag headline at him: "Greylock, Khosla fight. Homebrew stuck in the middle. ''Who me?'' Asks Hunter Walk."','self_published','subject_authored','https://x.com/sarahtavel','x.com','2023-09-05','2026-09-03T23:55:00Z',NULL,1,NULL,NULL,'run_ingest_tavel_20260903'),

-- ── every.to — public transcript. She spoke the words; Every published them ───
('f_tavel_018','m_tavel','Names her own board seats on the record: "I''m on the board of a company called Agentio, which is a marketplace for YouTube creators and brands... this has been a market that has eluded startups for a long time because most of them have kind of fallen into the quicksand of becoming an agency." And: "I''m on the board of a company called Chainalysis, so I''ve had a kind of seat in the crypto space and have been a long-term believer in Bitcoin."','on_record','subject_authored','https://every.to/podcast/transcript-c09360f3-efda-4688-952d-203b9f5f4315','every.to','2025-04-30','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_019','m_tavel','"My mom''s from Argentina and I can tell you everybody in Argentina wants a U.S. dollar. But it''s really hard to get them... I remember going to Argentina and having somebody on a motorcycle come to exchange money. That''s kind of what you would do."','on_record','subject_authored','https://every.to/podcast/transcript-c09360f3-efda-4688-952d-203b9f5f4315','every.to','2025-04-30','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_020','m_tavel','Carries a line from her Bessemer years as her test of a good board: "When I was at Bessemer, Jeremy Levine said that the best companies you want to be donut companies where you go to the board meeting, you eat a donut, and then you leave because they don''t really need you."','on_record','subject_authored','https://every.to/podcast/transcript-c09360f3-efda-4688-952d-203b9f5f4315','every.to','2025-04-30','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_021','m_tavel','Her stated taste in founders: "there''s some founders that it''s almost like a cool new job for them. And there''s some for whom it''s an affliction. And I''m attracted to the founders for whom it''s an affliction. You know, it''s this rash that they just have to scratch and that''s gonna make them run through whatever walls that they have to." And the tell she watches for: "I hate to say this, but they''re like, oh, that''s a good question. I hadn''t thought about that... That''s usually concerning."','on_record','subject_authored','https://every.to/podcast/transcript-c09360f3-efda-4688-952d-203b9f5f4315','every.to','2025-04-30','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_022','m_tavel','Keeps a written pre-mortem on every company she diligences, and names the source: "Annie Duke inspired this. She wrote this book Thinking in Bets. A pre-mortem — So every time I meet with a company and I dig in on it a little bit, I write to myself what I liked, what I didn''t like, what the deal would have been, and if I got yes, why? If I got no, why. And so it follows that over time, I''m gonna be able to look back on that list and examine my decision making process." She names one of her own misses in the same breath: "I know that there''s one example where I passed on a company because the valuation was too high. And that was a lesson to me of a company that ended up being a real success, this company Mercado."','on_record','subject_authored','https://every.to/podcast/transcript-c09360f3-efda-4688-952d-203b9f5f4315','every.to','2025-04-30','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

('f_tavel_023','m_tavel','On localising Pinterest, and the piece of advice from Ben Silbermann she still uses: "I remember when I was at Pinterest and I was responsible for all the discovery experiences and very early on I had to kind of localize Pinterest... I was thinking about the categories and all as being different. I remember Ben saying to me, just assume it''s gonna be more similar than different."','on_record','subject_authored','https://every.to/podcast/transcript-c09360f3-efda-4688-952d-203b9f5f4315','every.to','2025-04-30','2026-09-03T23:55:00Z',NULL,0,NULL,NULL,'run_ingest_tavel_20260903'),

